<script setup lang="ts">
import{computed,onMounted,reactive,ref}from'vue';import{api,apiMessage}from'@/api/client';import type{Mainline,MainlineItem}from'@/types';
const lines=ref<Mainline[]>([]);const selectedId=ref('');const error=ref('');const lineDraft=reactive({name:'',description:'',color:'#002FA7'});const itemDraft=reactive({title:'',description:'',acceptanceText:'完成本步骤',plannedMinutes:60});
const selected=computed(()=>lines.value.find(v=>v.id===selectedId.value)??lines.value[0]);
async function load(){lines.value=(await api.get<Mainline[]>('/mainlines')).data;if(!selectedId.value&&lines.value[0])selectedId.value=lines.value[0].id;}
async function createLine(){try{const{data}=await api.post<Mainline>('/mainlines',lineDraft);lineDraft.name='';lineDraft.description='';selectedId.value=data.id;await load();}catch(e){error.value=apiMessage(e);}}
async function addItem(){if(!selected.value)return;try{await api.post(`/mainlines/${selected.value.id}/items`,{title:itemDraft.title,description:itemDraft.description,acceptance:itemDraft.acceptanceText.split('\n').filter(Boolean),plannedMinutes:itemDraft.plannedMinutes,sortOrder:selected.value.items.length});itemDraft.title='';itemDraft.description='';await load();}catch(e){error.value=apiMessage(e);}}
async function action(item:MainlineItem,type:'start'|'pause'|'complete'){try{if(type==='complete')await api.post(`/mainlines/items/${item.id}/complete`,{note:'',version:item.version});else await api.post(`/mainlines/items/${item.id}/${type}`,null,{params:{version:item.version}});await load();}catch(e){error.value=apiMessage(e);}}
async function removeLine(){if(!selected.value||!confirm(`将主线“${selected.value.name}”移入回收站？`))return;try{await api.delete(`/mainlines/${selected.value.id}`);selectedId.value='';await load();}catch(e){error.value=apiMessage(e);}}
async function removeItem(item:MainlineItem){if(!confirm(`将步骤“${item.title}”移入回收站？`))return;try{await api.delete(`/mainlines/items/${item.id}`);await load();}catch(e){error.value=apiMessage(e);}}
onMounted(()=>load().catch(e=>error.value=apiMessage(e)));
</script>
<template><div class="page"><section class="page-head"><div><p class="eyebrow">MAINLINE / ORDERED TODO</p><h1>主线清单</h1></div><p>只有完成当前步骤，下一步才会解锁。</p></section><p v-if="error" class="error-text">{{error}}</p><div class="mainline-layout"><aside class="line-list"><button v-for="line in lines" :key="line.id" :class="{active:selected?.id===line.id}" @click="selectedId=line.id"><i :style="{background:line.color}"/><strong>{{line.name}}</strong><span>{{line.completed}}/{{line.total}}</span></button><form @submit.prevent="createLine"><input v-model="lineDraft.name" placeholder="新主线名称" required/><textarea v-model="lineDraft.description" placeholder="主线说明"/><div class="button-row"><input v-model="lineDraft.color" type="color"/><button class="btn primary">新建主线</button></div></form></aside><section v-if="selected" class="section"><header class="section-title"><div><p class="eyebrow">{{selected.completed}} / {{selected.total}}</p><h2>{{selected.name}}</h2><p>{{selected.description}}</p></div><button class="text-btn danger-text" @click="removeLine">移入回收站</button></header><article v-for="(item,index) in selected.items" :key="item.id" class="mainline-step" :class="{'locked':!item.unlocked}"><strong class="step-number">{{String(index+1).padStart(2,'0')}}</strong><div><span>{{item.status}}</span><h3>{{item.title}}</h3><p>{{item.description}}</p></div><div class="button-row"><button v-if="item.status!=='RUNNING'&&item.status!=='COMPLETED'" class="btn" :disabled="!item.unlocked" @click="action(item,'start')">开始</button><button v-if="item.status==='RUNNING'" class="btn" @click="action(item,'pause')">暂停</button><button v-if="item.status!=='COMPLETED'" class="btn primary" :disabled="!item.unlocked" @click="action(item,'complete')">完成</button><button class="text-btn danger-text" @click="removeItem(item)">移入回收站</button></div></article><form class="editor-card horizontal-editor" @submit.prevent="addItem"><h3>添加下一步</h3><label>标题<input v-model="itemDraft.title" required/></label><label>说明<input v-model="itemDraft.description"/></label><label>计划分钟<input v-model.number="itemDraft.plannedMinutes" type="number" min="1"/></label><button class="btn primary">添加</button></form></section><section v-else class="empty section">先创建一条主线。</section></div></div></template>
